let budget = Duration::from_secs(60);
loop {
    tokio::select! {
        Some(msg) = arrivals.recv() => handle(msg).await,   // arrival restarts the deadline
        _ = tokio::time::sleep(budget) => {
            tracing::error!(subject, "no messages for {:?}", budget);
        }
    }
}

